import { DomainError } from "./errors";

export type OrderState = "placed" | "paid" | "packed" | "shipped" | "delivered" | "cancelled";

export const FLOW: readonly OrderState[] = ["placed", "paid", "packed", "shipped", "delivered"];

export interface OrderLine {
  readonly productId: string;
  readonly quantity: number;
}

export class Order {
  private current: OrderState = "placed";

  constructor(
    readonly id: string,
    readonly customerId: string,
    readonly lines: readonly OrderLine[],
    readonly placedAt: Date,
  ) {}

  get state(): OrderState {
    return this.current;
  }

  /** Advances to the next state in the flow; only the immediate successor is allowed. */
  advanceTo(next: OrderState): void {
    const i = FLOW.indexOf(this.current);
    if (i < 0 || FLOW[i + 1] !== next) {
      throw new DomainError("invalid_transition", `cannot move order from ${this.current} to ${next}`);
    }
    this.current = next;
  }

  cancel(): void {
    if (this.current === "cancelled") {
      throw new DomainError("invalid_transition", "order is already cancelled");
    }
    if (FLOW.indexOf(this.current) >= FLOW.indexOf("shipped")) {
      throw new DomainError("invalid_transition", `cannot cancel an order that is ${this.current}`);
    }
    this.current = "cancelled";
  }
}

=====SOURCE-END=====

